  assert.deepEqual(callsA, [1, 2]);
  assert.equal(a.compensationStatus, 'completed');
  assert.deepEqual(
    a.compensationAttempts.map(r => [r.nodeId, r.operation, r.attempt, r.ok, r.result]),
